'use client'

import * as React from 'react'
import { Check, Copy } from 'iconoir-react'
import { cn } from '@/lib/utils'
import { Button } from '@/registry/satin/ui/button'
import { useSatinLabels } from '@/registry/satin/ui/labels'

/**
 * CodeBlock, 1:1 with the uiKit `CodeBlock` set (3179:20414) and its `CodeLine` rows
 * (3124:20131): a card-surface block, a border-default edge, radius-2xl, 12px bottom padding.
 * The header holds the file icon, the filename (medium 13/18), diff stats in a diff, and a
 * tertiary xs Copy button that reads "Copied" with a check for 1.5 s. Lines are Geist Mono
 * 13/19.5, 24 high, 16px side padding, a 20px right-aligned number column 16px from the
 * code (8px, plus an 8px sign column, in a diff).
 *
 * Line types: highlighted (code/line-highlight fill), added (status green bg, green number
 * and +), removed (status red bg, red number and −).
 *
 * `code` is plain text. In `view="diff"` each line starts with "+", "-" or a space, like a
 * unified diff. Highlighting is a small JS/TS tokenizer: keyword, string, function, parameter
 * and variable, in the `code/*` colours.
 *
 * The code scrolls sideways in a focusable region named "<filename> code" (`codeRegion`).
 * `aria-label` and `aria-labelledby` name that region instead, where they mean something: give
 * each block its own name when a page shows several with the same file name.
 *
 * The `code/*` variables exist only in Figma so far, not in theme.css, so each colour is
 * `var(--code-…, <Figma light value>)` with the Figma dark value under `dark:`. Once the
 * theme defines them, the variables take over.
 */

type LineKind = 'default' | 'highlighted' | 'added' | 'removed' | 'context'
type TokenKind = 'plain' | 'keyword' | 'string' | 'function' | 'parameter' | 'variable' | 'comment'

const tokenClass: Record<TokenKind, string> = {
  plain: 'sa:text-[var(--code-plain,#18181b)] sa:dark:text-[var(--code-plain,#fafafa)]',
  keyword: 'sa:text-[var(--code-keyword,#dc2626)] sa:dark:text-[var(--code-keyword,#f87171)]',
  string: 'sa:text-[var(--code-string,#0369a1)] sa:dark:text-[var(--code-string,#7dd3fc)]',
  function: 'sa:text-[var(--code-function,#8b5cf6)] sa:dark:text-[var(--code-function,#a78bfa)]',
  parameter: 'sa:text-[var(--code-parameter,#b45309)] sa:dark:text-[var(--code-parameter,#fcd34d)]',
  variable: 'sa:text-[var(--code-variable,#0284c7)] sa:dark:text-[var(--code-variable,#38bdf8)]',
  // No comment colour in Figma: comments take the line-number grey.
  comment: 'sa:text-[var(--code-line-number,#a1a1aa)] sa:dark:text-[var(--code-line-number,#71717a)]',
}

const lineNumberClass = 'sa:text-[var(--code-line-number,#a1a1aa)] sa:dark:text-[var(--code-line-number,#71717a)]'
const highlightClass = 'sa:bg-[var(--code-line-highlight,rgba(0,0,0,0.05))] sa:dark:bg-[var(--code-line-highlight,rgba(255,255,255,0.06))]'

const KEYWORDS = new Set([
  'import', 'from', 'export', 'default', 'async', 'await', 'function', 'return', 'const', 'let', 'var',
  'if', 'else', 'for', 'while', 'do', 'switch', 'case', 'break', 'continue', 'new', 'class', 'extends',
  'try', 'catch', 'finally', 'throw', 'typeof', 'instanceof', 'in', 'of', 'type', 'interface', 'as',
  'true', 'false', 'null', 'undefined', 'this', 'yield', 'void', 'delete', 'static', 'public', 'private',
])

type Token = { text: string; kind: TokenKind }

/** A deliberately small tokenizer for JS/TS-like code, one line at a time. */
function tokenize(line: string): Token[] {
  const out: Token[] = []
  const re = /(\/\/.*$)|("(?:[^"\\]|\\.)*"?|'(?:[^'\\]|\\.)*'?|`(?:[^`\\]|\\.)*`?)|([A-Za-z_$][\w$]*)|(=>|===|!==|==|=)|(\s+)|(.)/g
  let declaring = false // after const / let / var, until "="
  let params = false // inside a function's parameter list
  let depth = 0
  let afterFunction = false
  let m: RegExpExecArray | null
  while ((m = re.exec(line))) {
    const [text, comment, str, ident, op, space] = m
    if (comment) out.push({ text, kind: 'comment' })
    else if (str) out.push({ text, kind: 'string' })
    else if (space) out.push({ text, kind: 'plain' })
    else if (op) {
      if (op === '=') declaring = false
      out.push({ text, kind: 'keyword' })
    } else if (ident) {
      const rest = line.slice(re.lastIndex)
      if (KEYWORDS.has(ident)) {
        if (ident === 'const' || ident === 'let' || ident === 'var') declaring = true
        if (ident === 'function') afterFunction = true
        out.push({ text, kind: 'keyword' })
      } else if (params && /^\s*[:,)=?]/.test(rest)) out.push({ text, kind: 'parameter' })
      else if (/^\s*\(/.test(rest) || /^[A-Z]/.test(ident)) {
        // Calls and PascalCase names (types, components) take the function colour, as in Figma.
        if (afterFunction) params = true
        afterFunction = false
        out.push({ text, kind: 'function' })
      } else if (declaring) out.push({ text, kind: 'variable' })
      else out.push({ text, kind: 'plain' })
    } else {
      if (params && text === '(') depth++
      if (params && text === ')' && --depth <= 0) params = false
      out.push({ text, kind: 'plain' })
    }
  }
  // Merge neighbours of the same kind so the DOM stays small.
  return out.reduce<Token[]>((acc, t) => {
    const last = acc[acc.length - 1]
    if (last && last.kind === t.kind) last.text += t.text
    else acc.push({ ...t })
    return acc
  }, [])
}

type Line = { kind: LineKind; number: number; text: string }

function parse(code: string, view: 'code' | 'diff', highlightLines: number[]): Line[] {
  const raw = code.replace(/\n$/, '').split('\n')
  if (view === 'code') {
    return raw.map((text, i) => ({
      text,
      number: i + 1,
      kind: highlightLines.includes(i + 1) ? 'highlighted' : 'default',
    }))
  }
  // Diff: a removed line shows the number the next line will take; added and context count up.
  let n = 1
  return raw.map((line) => {
    const sign = line[0]
    const text = line.slice(1)
    if (sign === '-') return { text, number: n, kind: 'removed' as const }
    if (sign === '+') return { text, number: n++, kind: 'added' as const }
    return { text: sign === ' ' ? text : line, number: n++, kind: 'context' as const }
  })
}

/** The file icon from Figma (fileCode, 16 at 1.25). */
function FileCodeIcon() {
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden className="sa:shrink-0 sa:text-text-muted">
      <path
        d="M13.333 5.333L9.333 1.333H4C3.264 1.333 2.667 1.93 2.667 2.667V13.333C2.667 14.07 3.264 14.667 4 14.667H12C12.736 14.667 13.333 14.07 13.333 13.333V5.333ZM9.333 1.333V5.333H13.333M6.667 8.333L5.333 9.667L6.667 11M9.333 8.333L10.667 9.667L9.333 11"
        stroke="currentColor"
        strokeWidth="1.25"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  )
}

export interface CodeBlockProps extends Omit<React.ComponentProps<'div'>, 'children'> {
  code: string
  filename?: string
  view?: 'code' | 'diff'
  showHeader?: boolean
  showActions?: boolean
  /** 1-based line numbers to mark (code view). */
  highlightLines?: number[]
  /** Turn syntax colours off for plain output such as logs. */
  highlight?: boolean
}

export function CodeBlock({
  code,
  filename,
  view = 'code',
  showHeader = true,
  showActions = true,
  highlightLines = [],
  highlight = true,
  className,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledBy,
  ...props
}: CodeBlockProps) {
  const labels = useSatinLabels()
  const lines = React.useMemo(() => parse(code, view, highlightLines), [code, view, highlightLines])
  const [copied, setCopied] = React.useState(false)
  const timer = React.useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  React.useEffect(() => () => clearTimeout(timer.current), [])

  const added = lines.filter((l) => l.kind === 'added').length
  const removed = lines.filter((l) => l.kind === 'removed').length

  const copy = async () => {
    // A diff copies the new version of the file.
    const text = lines.filter((l) => l.kind !== 'removed').map((l) => l.text).join('\n')
    try {
      await navigator.clipboard.writeText(text)
      setCopied(true)
      clearTimeout(timer.current)
      timer.current = setTimeout(() => setCopied(false), 1500)
    } catch {
      setCopied(false)
    }
  }

  const diff = view === 'diff'
  // A change of view or code after the first render dissolves the new lines in rather than
  // cutting to them, so a switch reads as one motion with whatever control made it.
  const content = `${view}\n${code}`
  const firstContent = React.useRef(content)
  const fade = firstContent.current !== content

  return (
    <div
      data-slot="code-block"
      data-view={view}
      className={cn(
        'sa:flex sa:flex-col sa:overflow-hidden sa:rounded-2xl sa:border sa:border-border-default sa:bg-bg-card sa:pb-3',
        className,
      )}
      {...props}
    >
      {showHeader && (
        <div className="sa:flex sa:items-center sa:gap-2 sa:ps-4 sa:pe-2 sa:pt-2 sa:pb-1">
          <FileCodeIcon />
          <span className="sa:min-w-0 sa:flex-1 sa:truncate sa:text-sm sa:leading-[18px] sa:font-medium sa:text-text-default">{filename}</span>
          {diff && (
            <span className="sa:flex sa:shrink-0 sa:items-center sa:gap-1.5 sa:font-mono sa:text-sm sa:leading-(--sa-text-sm--line-height) sa:tracking-normal">
              <span className="sa:text-status-green-fg">+{added}</span>
              <span className="sa:text-status-red-fg">−{removed}</span>
            </span>
          )}
          {showActions && (
            <Button variant="tertiary" size="xs" onClick={copy} className="sa:text-text-default">
              {copied ? <Check /> : <Copy />}
              <span aria-live="polite">{copied ? labels.copied : labels.copy}</span>
            </Button>
          )}
        </div>
      )}
      {/* Long lines scroll sideways, so the code is a focusable region keyboard users can scroll.
          Code reads left to right in any page. */}
      <pre
        dir="ltr"
        tabIndex={0}
        role="region"
        aria-label={ariaLabelledBy ? undefined : (ariaLabel ?? labels.codeRegion(filename))}
        aria-labelledby={ariaLabelledBy}
        className={cn(
          'sa:outline-none sa:focus-visible:[box-shadow:inset_0_0_0_2px_var(--sa-action-focus-ring)]',
          'sa:overflow-x-auto sa:font-mono sa:text-sm sa:leading-(--sa-text-sm--line-height) sa:font-normal sa:tracking-normal',
          // Without the header the code sits in the middle: 12px above, as below.
          showHeader ? 'sa:pt-1' : 'sa:pt-3',
          tokenClass.plain,
        )}
      >
        <code key={content} className={cn('sa:block sa:w-max sa:min-w-full', fade && 'sa:animate-[satin-fade-in_var(--sa-duration-base)_var(--sa-ease-out)]')}>
          {lines.map((line, i) => (
            <span
              key={i}
              data-line={line.kind}
              className={cn(
                'sa:flex sa:h-6 sa:items-center sa:px-4',
                diff ? 'sa:gap-2' : 'sa:gap-4',
                line.kind === 'highlighted' && highlightClass,
                line.kind === 'added' && 'sa:bg-status-green-bg',
                line.kind === 'removed' && 'sa:bg-status-red-bg',
              )}
            >
              <span
                aria-hidden
                className={cn(
                  'sa:w-5 sa:shrink-0 sa:text-right sa:select-none',
                  line.kind === 'added' ? 'sa:text-status-green-fg' : line.kind === 'removed' ? 'sa:text-status-red-fg' : lineNumberClass,
                )}
              >
                {line.number}
              </span>
              {diff && (
                <span
                  className={cn(
                    'sa:w-2 sa:shrink-0 sa:text-center sa:select-none',
                    line.kind === 'added' ? 'sa:text-status-green-fg' : line.kind === 'removed' ? 'sa:text-status-red-fg' : lineNumberClass,
                  )}
                >
                  {line.kind === 'added' ? '+' : line.kind === 'removed' ? '−' : ' '}
                  {/* Screen readers hear the change, not the glyph. */}
                  {line.kind === 'added' && <span className="sa:sr-only"> {labels.added}</span>}
                  {line.kind === 'removed' && <span className="sa:sr-only"> {labels.removed}</span>}
                </span>
              )}
              <span className="sa:whitespace-pre">
                {line.text === ''
                  ? '​'
                  : highlight
                    ? tokenize(line.text).map((t, j) => (
                        <span key={j} className={t.kind === 'plain' ? undefined : tokenClass[t.kind]}>
                          {t.text}
                        </span>
                      ))
                    : line.text}
              </span>
            </span>
          ))}
        </code>
      </pre>
    </div>
  )
}
